1:# Checks for this ticket, written by the network team. Don't edit this file.
2:lab: topology.clab.yml
3:timeout: 90
5:checks:
6:  # --- The ticket: the customer's new block 10.101.0.0/24 must reach the upstream and the peer.
7:  - {type: route, node: up1, prefix: 10.101.0.0/24, protocol: bgp, name: "TICKET up1 receives the customer's new 10.101.0.0/24"}
8:  - {type: route, node: peer1, prefix: 10.101.0.0/24, protocol: bgp, name: "TICKET peer1 receives the customer's new 10.101.0.0/24"}
9:  - {type: ping, node: cust1, source: 10.101.0.1, target: 198.51.100.1, name: "TICKET the new block reaches the peer"}
11:  # --- Standing guards: what must stay true for every change on edge1.
12:  - {type: bgp_session, node: edge1, neighbor: 10.0.1.2, name: "GUARD session to cust1 up"}
13:  - {type: bgp_session, node: edge1, neighbor: 10.0.2.2, name: "GUARD session to up1 up"}
14:  - {type: bgp_session, node: edge1, neighbor: 10.0.3.2, name: "GUARD session to peer1 up"}
15:  - {type: route, node: up1, prefix: 192.0.2.0/24, protocol: bgp, name: "GUARD up1 receives our block"}
16:  - {type: route, node: peer1, prefix: 10.100.0.0/24, protocol: bgp, name: "GUARD peer1 receives the customer's 10.100.0.0/24"}
17:  - {type: ping, node: cust1, source: 10.100.0.1, target: 203.0.113.1, name: "GUARD customer reaches the internet via up1"}
18:  # Route-leak guards: never pass upstream routes to the peer or peer routes to the upstream,
19:  # and never accept customer routes outside the customer's registered blocks.
20:  - {type: route, node: peer1, prefix: 203.0.113.0/24, protocol: bgp, present: false, name: "LEAK GUARD peer1 must not get upstream routes"}
21:  - {type: route, node: peer1, prefix: 0.0.0.0/0, protocol: bgp, present: false, name: "LEAK GUARD peer1 must not get the upstream's default route"}
22:  - {type: route, node: up1, prefix: 198.51.100.0/24, protocol: bgp, present: false, name: "LEAK GUARD up1 must not get peer routes"}
23:  - {type: bgp_prefixes, node: peer1, neighbor: 10.0.3.1, max: 3, name: "LEAK GUARD peer1 gets at most our 3 prefixes"}
24:  # cust1 also announces 8.8.8.0/24, which it doesn't own. The customer filter must keep dropping it.
25:  - {type: route, node: edge1, prefix: 8.8.8.0/24, protocol: bgp, present: false, name: "LEAK GUARD edge1 rejects prefixes the customer doesn't own"}

